package ratelimiter

import (
	"testing"
	"time"
)

type fakeClock struct {
	now time.Time
}

func (f *fakeClock) Now() time.Time {
	return f.now
}

func (f *fakeClock) Since(t time.Time) time.Duration {
	return f.now.Sub(t)
}

func (f *fakeClock) advance(d time.Duration) {
	f.now = f.now.Add(d)
}

func TestNew(t *testing.T) {
	tests := []struct {
		name    string
		cap     float64
		rate    float64
		clock   Clock
		wantErr bool
	}{
		{"valid", 10, 1, &fakeClock{now: time.Now()}, false},
		{"zero capacity", 0, 1, &fakeClock{now: time.Now()}, true},
		{"negative capacity", -1, 1, &fakeClock{now: time.Now()}, true},
		{"zero rate", 10, 0, &fakeClock{now: time.Now()}, true},
		{"negative rate", 10, -1, &fakeClock{now: time.Now()}, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.cap, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Errorf("New() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

