			startTime: time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC),
			advances:  []time.Duration{0},
			allowNs:   []int{11},
			wantAllow: []bool{false},
		},
		{
			name:      "refill over time",
			cap:       10,
			rate:      1,
			startTime: time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC),
			advances:  []time.Duration{0, 5 * time.Second},
			allowNs:   []int{10, 5},
			wantAllow: []bool{true, true},
		},
